head.script:
scwin.gAcptNo; // 접수번호
scwin.gEmpNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(pnl_1);

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_again",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_again=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        scwin.setParamData();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10004.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_again_OnSuccess
 * @description again On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_again_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 기처리가 되었습니다.");
        await $c.win.closePopup();

        // 부모창 reload 처리해야함
        // frame.Provider("/frame_head").fn_HeadRead() ;
        // frame.Provider("../../frame_head").fn_HeadRead() ;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10004.trs_again_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_again_OnFail
 * @description again On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_again_OnFail = async function() {
    try {
        await $c.win.alert('trs_again.OnFail() :' + trs_again.ErrorMsg);
        dts_again.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10004.trs_again_OnFail" });
    }
};

/**
 * @method
 * @name btn_Cancle_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancle_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10004.btn_Cancle_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10004.btn_Save_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    const vReason = txa_AgainReason.getValue();
    if (vReason.length < 1) {
        await $c.win.alert("기처리 사유를 입력하시오.");
        txa_AgainReason.focus();
        return;
    }
    $c.stf.checkMaxLength(txa_AgainReason, 500, '기처리사유');
    dts_again.insertRow();
    dts_again.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_again.setCellData(1, "AGAIN_REASON", vReason);
    dts_again.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_again.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    const vAnswer = confirm('입력하신 사유로 기처리 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        trs_again.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_again",
            action : "/DisclosureStudy.do",
            ref : "dts_again",
            target : "trs_again=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParamData
 * @description 부모창의 데이타 셋팅하기
 * @returns {void}
 * @hidden N
 */
scwin.setParamData = function() {
    // gAcptNo = frame.Provider("/frame_head").dts_AcptProcs.NameString(1, 'ACPT_NO');
    scwin.gAcptNo = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'ACPT_NO');
    scwin.gEmpNo = js_emp_no; // 세션정보

};
